effect.shader:
// k/255 pelo mais perto, montado nos bits do float: o valor exato que a textura de 8 bits devolve (o
// `floor(..)/255.0` vai pelo recíproco e erra o último bit — ver `am-color-balance.xml`).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

vec3 oitoBits3(vec3 k) {
    return vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
}

vec3 linear(vec3 c) {
    return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c));
}

vec3 srgb(vec3 l) {
    l = clamp(l, 0.0, 1.0);
    return mix(l * 12.92, 1.055 * pow(l, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), l));
}

// Os bytes que um RT sRGB de 8 bits guarda para esta cor linear.
vec3 bytesSrgb(vec3 l) {
    return floor(srgb(l) * 255.0 + 0.5);
}

// O texel exato de uma imagem do tamanho da tela no pixel de pé (a linha 0 é a base, como nos RTs do Node): no
// buffer de camada (`acEntradaDePe` = 0, a linha 0 é o topo) a linha é espelhada. Lê a entrada e o mapa para os RTs de
// pé e o RT de pé para a saída — os espelhos se desfazem, e a conta do meio é a da tela.
vec4 texelDePe(highp sampler2D img) {
    ivec2 T = textureSize(img, 0);
    ivec2 p = ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0));
    if (acEntradaDePe != 1) p.y = T.y - 1 - p.y;
    return texelFetch(img, p, 0);
}

// O programa do Node, conta por conta (o `_displacement_source` é o `mapaRt`, o `_SourceTex` é o `camadaRt`).
// [uvNode]: o UV do Node (cresce para cima) — os RTs estão de pé, é o da tela.
vec4 deslocar(vec2 uvNode) {
    vec4 u_xlat0;
    bool u_xlatb1;
    vec2 u_xlat2;
    bvec2 u_xlatb2;
    vec4 u_xlat3;
    vec4 u_xlat4;
    float u_xlat6;
    float u_xlat7;
    bvec2 u_xlatb7;
    vec2 u_xlat12;
    bvec2 u_xlatb12;
    float u_xlat13;
    bool u_xlatb13;
    vec2 u_xlat14;
    bvec2 u_xlatb14;
    float u_xlat18;
    float u_xlat19;
    u_xlat0 = texture(mapaRt, acScreenNorm).yzwx;
    u_xlatb1 = keepEdge;
    if (useForHorizontal == 0) {
        u_xlat2.x = u_xlat0.w;
    } else {
        u_xlatb7.x = useForHorizontal == 1;
        if (u_xlatb7.x) {
            u_xlat2.x = u_xlat0.x;
        } else {
            u_xlatb7.x = useForHorizontal == 2;
            if (u_xlatb7.x) {
                u_xlat2.x = u_xlat0.y;
            } else {
                u_xlatb7.x = useForHorizontal == 3;
                if (u_xlatb7.x) {
                    u_xlat2.x = u_xlat0.z;
                } else {
                    u_xlatb7.x = useForHorizontal == 4;
                    if (u_xlatb7.x) {
                        u_xlat2.x = dot(u_xlat0.wxy, vec3(0.300000012, 0.589999974, 0.109999999));
                    } else {
                        u_xlatb7.x = u_xlat0.x >= u_xlat0.y;
                        u_xlat7 = u_xlatb7.x ? 1.0 : float(0.0);
                        u_xlat3.xy = u_xlat0.yx;
                        u_xlat3.z = float(-1.0);
                        u_xlat3.w = float(0.666666687);
                        u_xlat4.xy = u_xlat0.xy + (-u_xlat3.xy);
                        u_xlat4.z = float(1.0);
                        u_xlat4.w = float(-1.0);
                        u_xlat3 = vec4(u_xlat7) * u_xlat4 + u_xlat3;
                        u_xlatb7.x = u_xlat0.w >= u_xlat3.x;
                        u_xlat7 = u_xlatb7.x ? 1.0 : float(0.0);
                        u_xlat4.xyz = u_xlat3.xyw;
                        u_xlat4.w = u_xlat0.w;
                        u_xlat3.xyw = u_xlat4.wyx;
                        u_xlat3 = (-u_xlat4) + u_xlat3;
                        u_xlat3 = vec4(u_xlat7) * u_xlat3 + u_xlat4;
                        u_xlat7 = min(u_xlat3.y, u_xlat3.w);
                        u_xlat7 = (-u_xlat7) + u_xlat3.x;
                        u_xlat13 = (-u_xlat3.y) + u_xlat3.w;
                        u_xlat19 = u_xlat7 * 6.0 + 1.00000001e-10;
                        u_xlat13 = u_xlat13 / u_xlat19;
                        u_xlat13 = u_xlat13 + u_xlat3.z;
                        u_xlatb14.xy = equal(ivec4(useForHorizontal), ivec4(5, 6, 5, 6)).xy;
                        u_xlat19 = u_xlat3.x + 1.00000001e-10;
                        u_xlat7 = u_xlat7 / u_xlat19;
                        u_xlat7 = (u_xlatb14.y) ? u_xlat3.x : u_xlat7;
                        u_xlat2.x = (u_xlatb14.x) ? abs(u_xlat13) : u_xlat7;
                    }
                }
            }
        }
    }
    u_xlatb7.x = fromCenter;
    if (useForVertical == 0) {
        u_xlat2.y = u_xlat0.w;
    } else {
        u_xlatb13 = useForVertical == 1;
        if (u_xlatb13) {
            u_xlat2.y = u_xlat0.x;
        } else {
            u_xlatb13 = useForVertical == 2;
            if (u_xlatb13) {
                u_xlat2.y = u_xlat0.y;
            } else {
                u_xlatb13 = useForVertical == 3;
                if (u_xlatb13) {
                    u_xlat2.y = u_xlat0.z;
                } else {
                    u_xlatb13 = useForVertical == 4;
                    if (u_xlatb13) {
                        u_xlat2.y = dot(u_xlat0.wxy, vec3(0.300000012, 0.589999974, 0.109999999));
                    } else {
                        u_xlatb13 = u_xlat0.x >= u_xlat0.y;
                        u_xlat13 = u_xlatb13 ? 1.0 : float(0.0);
                        u_xlat3.xy = u_xlat0.yx;
                        u_xlat3.z = float(-1.0);
                        u_xlat3.w = float(0.666666687);
                        u_xlat4.xy = u_xlat0.xy + (-u_xlat3.xy);
                        u_xlat4.z = float(1.0);
                        u_xlat4.w = float(-1.0);
                        u_xlat3 = vec4(u_xlat13) * u_xlat4 + u_xlat3;
                        u_xlatb13 = u_xlat0.w >= u_xlat3.x;
                        u_xlat13 = u_xlatb13 ? 1.0 : float(0.0);
                        u_xlat0.xyz = u_xlat3.xyw;
                        u_xlat3.xyw = u_xlat0.wyx;
                        u_xlat3 = (-u_xlat0) + u_xlat3;
                        u_xlat0 = vec4(u_xlat13) * u_xlat3 + u_xlat0;
                        u_xlat13 = min(u_xlat0.y, u_xlat0.w);
                        u_xlat13 = u_xlat0.x + (-u_xlat13);
                        u_xlat6 = (-u_xlat0.y) + u_xlat0.w;
                        u_xlat18 = u_xlat13 * 6.0 + 1.00000001e-10;
                        u_xlat6 = u_xlat6 / u_xlat18;
                        u_xlat6 = u_xlat6 + u_xlat0.z;
                        u_xlatb12.xy = equal(ivec4(useForVertical), ivec4(5, 6, 5, 6)).xy;
                        u_xlat19 = u_xlat0.x + 1.00000001e-10;
                        u_xlat13 = u_xlat13 / u_xlat19;
                        u_xlat0.x = (u_xlatb12.y) ? u_xlat0.x : u_xlat13;
                        u_xlat2.y = (u_xlatb12.x) ? abs(u_xlat6) : u_xlat0.x;
                    }
                }
            }
        }
    }
    u_xlat0.xy = u_xlat2.xy + vec2(-0.5, -0.5);
    u_xlat0.xy = (u_xlatb7.x) ? u_xlat2.xy : u_xlat0.xy;
    u_xlat0.xy = vec2(maxHorizontal, maxVertical) * u_xlat0.xy + uvNode;
    u_xlat12.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat12.xy = u_xlat12.xy * vec2(1.00100005, 1.00100005) + vec2(0.5, 0.5);
    u_xlatb7.xy = lessThan(u_xlat12.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb2.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat12.xyxx).xy;
    u_xlat14.xy = fract(u_xlat12.xy);
    u_xlat14.xy = (-u_xlat14.xy) + vec2(1.0, 1.0);
    u_xlat2.x = (u_xlatb2.x) ? u_xlat14.x : u_xlat12.x;
    u_xlat2.y = (u_xlatb2.y) ? u_xlat14.y : u_xlat12.y;
    {
        vec2 hlslcc_movcTemp = u_xlat12;
        hlslcc_movcTemp.x = (u_xlatb7.x) ? (-u_xlat12.x) : u_xlat2.x;
        hlslcc_movcTemp.y = (u_xlatb7.y) ? (-u_xlat12.y) : u_xlat2.y;
        u_xlat12 = hlslcc_movcTemp;
    }
    u_xlat12.xy = u_xlat12.xy + vec2(-0.5, -0.5);
    u_xlat12.xy = u_xlat12.xy * vec2(0.999000967, 0.999000967) + vec2(0.5, 0.5);
    u_xlat0.xy = (bool(u_xlatb1)) ? u_xlat12.xy : u_xlat0.xy;
    return texture(camadaRt, u_xlat0.xy);
}

void main() {
    if (acPass == 0) {
        // A camada como o RT dela no Node: a cor em luz linear vezes o alfa, de pé; a GPU guarda em sRGB.
        vec4 c = texelDePe(inputImg);
        fragColor = vec4(linear(c.rgb) * c.a, c.a);
        return;
    }
    if (acPass == 1) {
        // O mapa, igual (o RT da camada escolhida; sem nenhuma, a própria camada).
        vec4 m = texelDePe(mapImg);
        fragColor = vec4(linear(m.rgb) * m.a, m.a);
        return;
    }
    if (acPass == 2) {
        // Os RTs estão de pé: o UV do Node é o da tela, nos dois casos.
        fragColor = deslocar(acScreenNorm);
        return;
    }

    // Os bytes do RT de saída do Node (a GPU decodificou ao ler; codificar de novo devolve o byte guardado), de volta
    // à orientação da entrada.
    vec4 o = texelDePe(saidaRt);
    vec3 kc = bytesSrgb(o.rgb);
    float ka = floor(o.a * 255.0 + 0.5);
    if (ka <= 0.0) {
        fragColor = vec4(0.0);
        return;
    }
    if (ka >= 255.0) {
        fragColor = vec4(oitoBits3(kc), 1.0);
        return;
    }
    // O Nova guarda reto: a cor linear guardada dividida pelo alfa, de volta ao sRGB (acima de 1 fica em 1).
    float a = oitoBits(ka);
    fragColor = vec4(srgb(min(linear(oitoBits3(kc)) / a, vec3(1.0))), a);
}
